import type { NodeMap } from '../compiler/types.ts';
import { languageApiName } from './engine.ts';

export interface EmitIndexConfig {
	grammar: string;
	nodeMap: NodeMap;
}

export function emitIndex(config: EmitIndexConfig): string {
	const api = languageApiName(config.grammar);
	return [
		'// Auto-generated by @sittir/codegen — do not edit',
		'',
		"import type { Language } from '@sittir/types';",
		`import type { ${api} } from './api.js';`,
		'',
		`export type { ${api} } from './api.js';`,
		'',
		`const ${config.grammar}: Language<${api}> = { name: '${config.grammar}', load: () => import('./api.js').then((m) => m.hooks) };`,
		`export default ${config.grammar};`,
		'',
		"export type * from './types.js';",
		"export type * from './options.js';",
		"export type { IsGuards } from './is.js';",
		"export type { Edit, CSTNode } from '@sittir/types';",
		"export { isEmpty } from './utils.js';",
		''
	].join('\n');
}
